129	absl::Status GetCapturedInput(const CapturedFunction* const func, int index,
130	                              const Tensor** out) {
131	  if (TF_PREDICT_FALSE(index >= func->captured_inputs().size())) {
132	    return absl::OutOfRangeError(absl::StrCat(
133	        "Out of range access to captured inputs for function ",
134	        func->func().name(), ". Index: ", index,
135	        ". Num captured inputs: ", func->captured_inputs().size()));
136	  }
137	  *out = &func->captured_inputs()[index];
138	  return absl::OkStatus();
139	}
