141	absl::Status RunShortCircuit(const ShortCircuitInfo& info,
142	                             const std::vector<Tensor>& args,
143	                             const CapturedFunction* const func,
144	                             std::vector<Tensor>* rets) {
145	  VLOG(3) << "Running function " << func->func().name() << " short circuit";
146	  const int num_args = args.size();
147	  rets->reserve(info.indices.size());
148	  for (size_t i = 0; i < info.indices.size(); ++i) {
149	    if (info.indices[i] < num_args) {
150	      rets->push_back(args[info.indices[i]]);
151	    } else {
152	      const Tensor* captured_input;
153	      TF_RETURN_IF_ERROR(
154	          GetCapturedInput(func, info.indices[i] - num_args, &captured_input));
155	      rets->push_back(*captured_input);
156	    }
157	  }
158	  return absl::OkStatus();
159	}
