161	absl::Status RunShortCircuit(const ShortCircuitInfo& info,
162	                             std::vector<Tensor>&& args,
163	                             const CapturedFunction* const func,
164	                             std::vector<Tensor>* rets) {
165	  VLOG(3) << "Running function " << func->func().name() << " short circuit";
166	  const int num_args = args.size();
167	  rets->reserve(info.indices.size());
168	  for (size_t i = 0; i < info.indices.size(); ++i) {
169	    if (info.indices[i] < num_args) {
170	      if (info.can_move[i]) {
171	        rets->push_back(std::move(args[info.indices[i]]));
172	      } else {
173	        rets->push_back(args[info.indices[i]]);
174	      }
175	    } else {
176	      const Tensor* captured_input;
177	      TF_RETURN_IF_ERROR(
178	          GetCapturedInput(func, info.indices[i] - num_args, &captured_input));
179	      rets->push_back(*captured_input);
180	    }
181	  }
182	  return absl::OkStatus();
183	}
