185	absl::Status CreateShortCircuitInfo(OpKernelConstruction* ctx,
186	                                    const NameAttrList& func,
187	                                    ShortCircuitInfo* info) {
188	  auto& indices = info->indices;
189	
190	  FunctionLibraryRuntime::Handle fn_handle;
191	  TF_RETURN_IF_ERROR(ctx->function_library()->Instantiate(
192	      func.name(), AttrSlice(&func.attr()), &fn_handle));
193	  auto cleanup = gtl::MakeCleanup([ctx, fn_handle]() {
194	    absl::Status s = ctx->function_library()->ReleaseHandle(fn_handle);
195	    if (!s.ok()) {
196	      LOG(WARNING) << "Failed to release handle: " << s.message();
197	    }
198	  });
199	
200	  // If the function contains any stateful operations, we conservatively execute
201	  // the entire function.
202	  if (ctx->function_library()->IsStateful(func.name())) {
203	    return absl::OkStatus();
204	  }
205	
206	  const FunctionBody* fn_body =
207	      ctx->function_library()->GetFunctionBody(fn_handle);
208	  indices.resize(fn_body->ret_nodes.size());
209	
210	  for (size_t i = 0; i < fn_body->ret_nodes.size(); ++i) {
211	    Node* ret_node = fn_body->ret_nodes[i];
212	    Node* ret_input_node;
213	    TF_RETURN_IF_ERROR(ret_node->input_node(0, &ret_input_node));
214	
215	    while (ret_input_node->def().op() == "Identity") {
216	      TF_RETURN_IF_ERROR(ret_input_node->input_node(0, &ret_input_node));
217	    }
218	
219	    if (ret_input_node->def().op() == FunctionLibraryDefinition::kArgOp) {
220	      TF_RETURN_IF_ERROR(
221	          GetNodeAttr(ret_input_node->def(), "index", &(indices[i])));
222	    } else {
223	      indices.clear();
224	      break;
225	    }
226	  }
227	
228	  // Compute the `can_move` vector.
229	  if (!indices.empty()) {
230	    auto& can_move = info->can_move;
231	    std::map<int, int> last_use;
232	    for (size_t i = 0; i < indices.size(); ++i) {
233	      last_use[indices[i]] = i;
234	    }
235	    can_move.resize(indices.size());
236	    for (int i = 0, end = indices.size(); i < end; ++i) {
237	      can_move[i] = last_use[indices[i]] == i;
238	    }
239	  }
240	
241	  return absl::OkStatus();
242	}
