244	absl::Status CreateFunctionLibraryDefinition(
245	    const FunctionLibraryDefinition* lib_def, const std::string& func_name,
246	    std::unique_ptr<FunctionLibraryDefinition>* result) {
247	  DCHECK(lib_def != nullptr);
248	  const FunctionDef* fdef = lib_def->Find(func_name);
249	  if (TF_PREDICT_FALSE(fdef == nullptr)) {
250	    return absl::FailedPreconditionError(absl::StrCat(
251	        "Could not find required function definition ", func_name));
252	  }
253	  *result = std::make_unique<FunctionLibraryDefinition>(
254	      lib_def->ReachableDefinitions(*fdef));
255	  return (*result)->CopyFunctionDefFrom(func_name, *lib_def);
256	}
