269	class CallFrameBase : public CallFrameInterface {
270	 public:
271	  explicit CallFrameBase(DataTypeSlice ret_types)
272	      : ret_types_(ret_types), retvals_(ret_types.size()) {}
273	
274	  // Caller methods.
275	  absl::Status ConsumeRetvals(std::vector<Tensor>* retvals) {
276	    retvals->reserve(retvals_.size());
277	    int i = 0;
278	    for (auto&& val : retvals_) {
279	      if (!val) {
280	        return absl::InternalError(
281	            absl::StrCat("No return value for index ", i, "."));
282	      }
283	      retvals->emplace_back(std::move(val.value()));
284	      ++i;
285	    }
286	    return absl::OkStatus();
287	  }
288	
289	  size_t num_retvals() const override { return retvals_.size(); }
290	
291	  // Callee methods.
292	  absl::Status SetRetval(int index, const Tensor& val) override {
293	    const int retvals_size = retvals_.size();
294	    if (index < retvals_size && val.dtype() == ret_types_[index] &&
295	        !retvals_[index]) {
296	      retvals_[index] = val;
297	      return absl::OkStatus();
298	    } else if (index >= retvals_size) {
299	      return absl::InvalidArgumentError(
300	          absl::StrCat("Return value ", index, " is out of range."));
301	    } else if (val.dtype() != ret_types_[index]) {
302	      return absl::InvalidArgumentError(
303	          absl::StrCat("Expected type ", DataTypeString(ret_types_[index]),
304	                       " for return value ", index, " but got ",
305	                       DataTypeString(val.dtype()), "."));
306	    } else {
307	      return absl::InternalError(absl::StrCat("Attempted to set return value ",
308	                                              index, " more than once."));
309	    }
310	  }
311	
312	 private:
313	  DataTypeSlice ret_types_;
314	  std::vector<std::optional<Tensor>> retvals_;
315	  CallFrameBase(const CallFrameBase&) = delete;
316	  void operator=(const CallFrameBase&) = delete;
317	};
