319	class OwnedArgsCallFrame : public CallFrameBase {
320	 public:
321	  OwnedArgsCallFrame(std::vector<Tensor>&& args,
322	                     const std::vector<Tensor>* captured_inputs,
323	                     DataTypeSlice ret_types)
324	      : CallFrameBase(ret_types),
325	        args_(std::move(args)),
326	        captured_inputs_(captured_inputs) {}
327	
328	  size_t num_args() const override {
329	    return args_.size() + captured_inputs_->size();
330	  }
331	
332	  // Callee methods.
333	  absl::Status GetArg(int index, const Tensor** val) override {
334	    const int args_size = args_.size();
335	    const int captured_inputs_size = captured_inputs_->size();
336	    if (index < args_size) {
337	      *val = &args_[index];
338	      return absl::OkStatus();
339	    } else if (index < args_size + captured_inputs_size) {
340	      *val = &(*captured_inputs_)[index - args_.size()];
341	      return absl::OkStatus();
342	    } else {
343	      return absl::InvalidArgumentError(
344	          absl::StrCat("Argument ", index, " is out of range."));
345	    }
346	  }
347	
348	  // Since we own the argument tensors in `args_`, we can implement
349	  // `ConsumeArg()` for those arguments.
350	  void ConsumeArg(int index, Tensor* val) override {
351	    DCHECK_GE(index, 0);
352	    DCHECK_LT(index, args_.size());
353	    *val = std::move(args_[index]);
354	  }
355	  bool CanConsumeArg(int index) const override {
356	    return index >= 0 && index < static_cast<int>(args_.size());
357	  }
358	
359	 private:
360	  std::vector<Tensor> args_;
361	  const std::vector<Tensor>* const captured_inputs_;  // Not owned.
362	};
