410	absl::Status MakeIteratorFromInputElement(
411	    IteratorContext* ctx, const DatasetBaseIterator* parent,
412	    const std::vector<Tensor>& input_element, int64_t thread_index,
413	    const InstantiatedCapturedFunction& inst_captured_func,
414	    absl::string_view prefix, std::unique_ptr<IteratorBase>* out_iterator,
415	    const std::shared_ptr<model::Node>& node) {
416	  std::vector<Tensor> return_values;
417	
418	  auto status = inst_captured_func.RunWithBorrowedArgs(ctx, input_element,
419	                                                       &return_values, node);
420	  if (!status.ok()) {
421	    return parent->AddErrorContext(status);
422	  }
423	
424	  if (!(return_values.size() == 1 && return_values[0].dtype() == DT_VARIANT &&
425	        TensorShapeUtils::IsScalar(return_values[0].shape()))) {
426	    return absl::InvalidArgumentError(
427	        "Function must return a single scalar of dtype DT_VARIANT.");
428	  }
429	
430	  // Retrieve the dataset that was created in `f`.
431	  DatasetBase* returned_dataset;
432	  TF_RETURN_IF_ERROR(
433	      GetDatasetFromVariantTensor(return_values[0], &returned_dataset));
434	
435	  // Create an iterator for the dataset that was returned by `f`.
436	  std::string iterator_prefix = absl::StrCat(prefix, "[", thread_index, "]");
437	
438	  IteratorContext nested_ctx = MakeNestedIteratorContext(ctx);
439	  TF_RETURN_IF_ERROR(returned_dataset->MakeIterator(
440	      &nested_ctx, parent, iterator_prefix, out_iterator));
441	  ctx->MergeCheckpoint(nested_ctx.checkpoint());
442	  return absl::OkStatus();
443	}
