454	absl::Status FunctionMetadata::Create(
455	    OpKernelConstruction* ctx, NameAttrList&& func, Params params,
456	    std::shared_ptr<FunctionMetadata>* out_metadata) {
457	  out_metadata->reset(new FunctionMetadata(std::move(func), params));
458	  TF_RETURN_IF_ERROR(CreateFunctionLibraryDefinition(
459	      ctx->function_library()->GetFunctionLibraryDefinition(),
460	      (*out_metadata)->func_.name(), &(*out_metadata)->lib_def_));
461	  TF_RETURN_IF_ERROR(CreateShortCircuitInfo(
462	      ctx, (*out_metadata)->func_, &(*out_metadata)->short_circuit_info_));
463	  const FunctionDef* fdef;
464	  TF_RETURN_IF_ERROR(LookupFunction(*(*out_metadata)->lib_def(),
465	                                    (*out_metadata)->func().name(), &fdef));
466	
467	  auto attr = fdef->attr().find(FunctionLibraryDefinition::kIntsOnDeviceAttr);
468	  if (attr != fdef->attr().end() && attr->second.b()) {
469	    VLOG(1) << "Disabling multi-device execution for a function that uses the "
470	            << FunctionLibraryDefinition::kIntsOnDeviceAttr << " attribute.";
471	    (*out_metadata)->use_multi_device_function_ = false;
472	    return absl::OkStatus();
473	  }
474	  auto validate_arg = [](const OpDef::ArgDef& arg) {
475	    if (!arg.number_attr().empty() || !arg.type_list_attr().empty()) {
476	      VLOG(1) << "Disabling multi-device execution for a function with "
477	              << "a vector argument " << arg.name() << ".";
478	      return false;
479	    }
480	    return true;
481	  };
482	  for (const auto& arg : fdef->signature().input_arg()) {
483	    if (!validate_arg(arg)) {
484	      (*out_metadata)->use_multi_device_function_ = false;
485	      return absl::OkStatus();
486	    }
487	  }
488	  for (const auto& arg : fdef->signature().output_arg()) {
489	    if (!validate_arg(arg)) {
490	      (*out_metadata)->use_multi_device_function_ = false;
491	      return absl::OkStatus();
492	    }
493	  }
494	  return absl::OkStatus();
495	}
