519	absl::Status CapturedFunction::AddToGraph(
520	    SerializationContext* ctx, DatasetBase::DatasetGraphDefBuilder* b,
521	    std::vector<Node*>* other_arguments,
522	    DataTypeVector* other_arguments_types) const {
523	  other_arguments->reserve(captured_inputs_.size());
524	  other_arguments_types->reserve(captured_inputs_.size());
525	  for (const Tensor& t : captured_inputs_) {
526	    Node* node;
527	    if (!ctx->is_graph_rewrite()) {
528	      TF_RETURN_IF_ERROR(b->AddDatasetOrTensor(ctx, t, &node));
529	    } else {
530	      TF_RETURN_IF_ERROR(b->AddPlaceholder(t, &node));
531	      DCHECK_NE(ctx->input_list(), nullptr);
532	      ctx->input_list()->emplace_back(node->name(), t);
533	    }
534	    other_arguments->emplace_back(node);
535	    other_arguments_types->emplace_back(t.dtype());
536	  }
537	  TF_RETURN_IF_ERROR(
538	      b->AddFunction(ctx, metadata_->func().name(), *metadata_->lib_def()));
539	  return absl::OkStatus();
540	}
