549	// TODO(b/190831948): Check whether the function creates a resource and if so,
550	// produce a warning.
551	absl::Status CapturedFunction::Instantiate(
552	    InstantiateCapturedFunctionParams params,
553	    std::unique_ptr<InstantiatedCapturedFunction>*
554	        instantiated_captured_function) {
555	  // The context's runtime will be used for all subsequent calls.
556	  FunctionLibraryRuntime* lib = params.flr;
557	  FunctionLibraryRuntime::InstantiateOptions inst_opts;
558	  inst_opts.lib_def = metadata_->lib_def();
559	  inst_opts.create_kernels_eagerly = true;
560	  inst_opts.default_device_to_target = metadata_->use_default_device();
561	  inst_opts.config_proto =
562	      lib->config_proto() ? *lib->config_proto() : ConfigProto();
563	  if (GetExperiments().contains(kAllowSmallFunctionOptimizations)) {
564	    inst_opts.allow_small_function_optimizations = true;
565	  } else {
566	    if (!metadata_->use_inter_op_parallelism()) {
567	      inst_opts.executor_type = "SINGLE_THREADED_EXECUTOR";
568	    }
