726	  Device* current_device = flr->device();
727	  DeviceType current_device_type(current_device->device_type());
728	  DeviceNameUtils::ParsedName current_device_name;
729	  if (!DeviceNameUtils::ParseFullName(current_device->name(),
730	                                      &current_device_name)) {
731	    return absl::InvalidArgumentError(
732	        absl::StrCat("Failed to parse device name: ", current_device->name()));
733	  }
734	
735	  // Check if any of the captured inputs are placed on a device not compatible
736	  // with the current device. For non-captured inputs, we assume they are placed
737	  // on the current device.
738	  for (const auto& input : captured_inputs_) {
739	    DataType dtype = input.dtype();
