759	  // Check if all ops could be placed on the current device.
760	  for (const auto& name : metadata_->lib_def()->ListFunctionNames()) {
761	    const FunctionDef* fdef;
762	    TF_RETURN_IF_ERROR(LookupFunction(*metadata_->lib_def(), name, &fdef));
